head.script:
scwin.onpageload = function () {

};

/**
 * GridView 'grd_exam1'의 'customType' 컬럼의 'typeGetter' 속성에 설정된 메소드
 * 동적으로 셀의 'inputType'을 설정
 */
scwin.getCustomType = function (info) {
    // console.log(info);
    let rowIndex = info.rowIndex;
    let colIndex = info.colIndex;
    let returnInfo = {
        options: {
            readOnly: "false",
            viewType: "default",
            chooseOption: "false",
            textAlign: "center"
        }
    };

    let _inputType = dlt_exam.getCellData(rowIndex, "inputType");

    switch (_inputType) {
        case "autoComplete":
            returnInfo.itemSet = {
                nodeset: "data:dlt_code",
                label: "codeName",
                value: "code"
            };
            returnInfo.options.viewType = "icon";
            returnInfo.options.chooseOption = "true";
            break;
        case "button":
            break;
        case "calendar":
            returnInfo.options.viewType = "icon";
            break;
        case "checkbox":
            returnInfo.options.checkboxLabel = "checkbox";
            returnInfo.options.valueType = "other";
            returnInfo.options.trueValue = "Y";
            returnInfo.options.falseValue = "N";
            break;
        case "checkcombobox":
            returnInfo.itemSet = {
                nodeset: "data:dlt_code",
                label: "codeName",
                value: "code"
            };
            returnInfo.options.viewType = "icon";
            returnInfo.options.chooseOption = "true";
            break;
        case "image":
            break;
        case "link":
            break;
        case "radio":
            returnInfo.options.checkboxLabel = "radio";
            returnInfo.options.valueType = "other";
            returnInfo.options.trueValue = "Y";
            returnInfo.options.falseValue = "N";
            break;
        case "secret":
            break;
        case "select":
            returnInfo.itemSet = {
                nodeset: "data:dlt_code",
                label: "codeName",
                value: "code"
            };
            returnInfo.options.viewType = "icon";
            returnInfo.options.chooseOption = "true";
            break;
        case "spinner":
            returnInfo.options.viewType = "icon";
            break;
        case "textarea":
            break;
        case "textImage":
            returnInfo.options.viewType = "icon";
            returnInfo.options.imageSrc = "/img/icons_search_type2.png";
            returnInfo.options.imageHeight = "20";
            returnInfo.options.readOnly = "true";
            break;
        case "text":
        default:
            break;
    }

    returnInfo.id = "dynamic_" + _inputType + "_" + rowIndex + "_" + colIndex;
    returnInfo.inputType = _inputType;

    return returnInfo;

};

/**
 * 사용자가 셀 수정 후 이벤트
 */
scwin.grd_ex01_onafteredit = function (row, col, value) {
    let colId = this.getColumnID(col);

    if (colId != "inputType") { return; }

    let cellData = "";
    switch (value) {
        case "autoComplete":
            cellData = "03";
            break;
        case "button":
            cellData = "button";
            break;
        case "calendar":
            cellData = "20241231";
            break;
        case "checkbox":
            cellData = "Y";
            break;
        case "checkcombobox":
            cellData = "03";
            break;
        case "image":
            cellData = "/img/btn_sub_setting.png";
            break;
        case "link":
            cellData = "link";
            break;
        case "radio":
            cellData = "N";
            break;
        case "secret":
            cellData = "secret";
            break;
        case "select":
            cellData = "03";
            break;
        case "spinner":
            cellData = "12";
            break;
        case "textarea":
            cellData = "textarea";
            break;
        case "textImage":
            cellData = "textImage";
            break;
        case "text":
        default:
            cellData = "text";
            break;
    }

    // 셀에 데이터를 설정하면 'customType' 컬럼의 'typeGetter'에 설정된 메소드가 호출됩니다.
    dlt_exam.setCellData(row, "customType", cellData);
};
